-- Evaluates the traders' animation data (MarketMotion, generated by blender/build_characters.py) exactly
-- like blender/village/characters.py does: keys per channel (Euler degrees in figure axes), monotone
-- cubic interpolation between keys (Fritsch-Butland slopes: no overshoot, flat at holds and turning
-- points, cyclic across the seam of a loop), channel -> bone shares, a breathing term on spine01 and an
-- additive greeting.  Returns local rotations as quaternions {x, y, z, w} in the Roblox frame of the
-- figure.  Pure Lua (no Roblox types), so the same file is tested against the Python side.
local Pose = {}

local function rot(ax, ay, az, deg)
	local n = math.sqrt(ax * ax + ay * ay + az * az)
	local x, y, z = ax / n, ay / n, az / n
	local t = math.rad(deg)
	local c, s = math.cos(t), math.sin(t)
	local k = 1 - c
	return {
		{ c + x * x * k, x * y * k - z * s, x * z * k + y * s },
		{ y * x * k + z * s, c + y * y * k, y * z * k - x * s },
		{ z * x * k - y * s, z * y * k + x * s, c + z * z * k },
	}
end
Pose.rot = rot

local function mul(a, b)
	local m = {}
	for i = 1, 3 do
		m[i] = {}
		for j = 1, 3 do
			m[i][j] = a[i][1] * b[1][j] + a[i][2] * b[2][j] + a[i][3] * b[3][j]
		end
	end
	return m
end
Pose.mul = mul

-- Rz @ Ry @ Rx (figure axes), as characters._euler
local function euler(rx, ry, rz)
	return mul(mul(rot(0, 0, 1, rz), rot(0, 1, 0, ry)), rot(1, 0, 0, rx))
end
Pose.euler = euler

-- figure (x, y, z) -> Roblox (x, z, -y): Rr = T R T^T
local function toRoblox(R)
	return {
		{ R[1][1], R[1][3], -R[1][2] },
		{ R[3][1], R[3][3], -R[3][2] },
		{ -R[2][1], -R[2][3], R[2][2] },
	}
end

local function quat(m)
	local tr = m[1][1] + m[2][2] + m[3][3]
	local x, y, z, w
	if tr > 0 then
		local s = math.sqrt(tr + 1) * 2
		w = 0.25 * s
		x = (m[3][2] - m[2][3]) / s
		y = (m[1][3] - m[3][1]) / s
		z = (m[2][1] - m[1][2]) / s
	elseif m[1][1] > m[2][2] and m[1][1] > m[3][3] then
		local s = math.sqrt(1 + m[1][1] - m[2][2] - m[3][3]) * 2
		w = (m[3][2] - m[2][3]) / s
		x = 0.25 * s
		y = (m[1][2] + m[2][1]) / s
		z = (m[1][3] + m[3][1]) / s
	elseif m[2][2] > m[3][3] then
		local s = math.sqrt(1 + m[2][2] - m[1][1] - m[3][3]) * 2
		w = (m[1][3] - m[3][1]) / s
		x = (m[1][2] + m[2][1]) / s
		y = 0.25 * s
		z = (m[2][3] + m[3][2]) / s
	else
		local s = math.sqrt(1 + m[3][3] - m[1][1] - m[2][2]) * 2
		w = (m[2][1] - m[1][2]) / s
		x = (m[1][3] + m[3][1]) / s
		y = (m[2][3] + m[3][2]) / s
		z = 0.25 * s
	end
	return { x, y, z, w }
end
Pose.quat = quat

-- slopes of one component (see characters._tangents)
local function tangents(ts, ys, cyclic, duration)
	local n = #ts
	local T, Y = {}, {}
	if cyclic and n > 2 then
		T[1], Y[1] = ts[n - 1] - duration, ys[n - 1]
		for i = 1, n do
			T[i + 1], Y[i + 1] = ts[i], ys[i]
		end
		T[n + 2], Y[n + 2] = ts[2] + duration, ys[2]
	else
		for i = 1, n do
			T[i], Y[i] = ts[i], ys[i]
		end
	end
	local N = #T
	local h, d, m = {}, {}, {}
	for k = 1, N - 1 do
		h[k] = T[k + 1] - T[k]
		d[k] = h[k] > 0 and (Y[k + 1] - Y[k]) / h[k] or 0
	end
	for k = 1, N do
		m[k] = 0
	end
	for k = 2, N - 1 do
		if d[k - 1] * d[k] > 0 then
			m[k] = 3 * (h[k - 1] + h[k]) / ((2 * h[k] + h[k - 1]) / d[k - 1] + (h[k] + 2 * h[k - 1]) / d[k])
		end
	end
	if cyclic and n > 2 then
		local out = {}
		for i = 1, n do
			out[i] = m[i + 1]
		end
		return out
	end
	return m
end

-- a track: keys {{t, v1, v2, ...}, ...}; prepared once (times, values per component, slopes)
local function prepare(keys, cyclic, duration)
	local ts, comps = {}, {}
	local dim = #keys[1] - 1
	for c = 1, dim do
		comps[c] = {}
	end
	for i, k in ipairs(keys) do
		ts[i] = k[1]
		for c = 1, dim do
			comps[c][i] = k[c + 1]
		end
	end
	local slopes = {}
	for c = 1, dim do
		slopes[c] = tangents(ts, comps[c], cyclic, duration)
	end
	return { ts = ts, ys = comps, ms = slopes, dim = dim }
end

local function sample(track, t, out)
	local ts = track.ts
	local n = #ts
	if t <= ts[1] then
		for c = 1, track.dim do
			out[c] = track.ys[c][1]
		end
		return out
	end
	if t >= ts[n] then
		for c = 1, track.dim do
			out[c] = track.ys[c][n]
		end
		return out
	end
	local j = 1
	for i = 1, n - 1 do
		if ts[i] <= t then
			j = i
		end
	end
	local h = ts[j + 1] - ts[j]
	if h <= 0 then
		for c = 1, track.dim do
			out[c] = track.ys[c][j + 1]
		end
		return out
	end
	local u = (t - ts[j]) / h
	local u2, u3 = u * u, u * u * u
	local h00, h10, h01, h11 = 2 * u3 - 3 * u2 + 1, u3 - 2 * u2 + u, -2 * u3 + 3 * u2, u3 - u2
	for c = 1, track.dim do
		local ys, ms = track.ys[c], track.ms[c]
		out[c] = h00 * ys[j] + h10 * h * ms[j] + h01 * ys[j + 1] + h11 * h * ms[j + 1]
	end
	return out
end

-- prepares a role of MarketMotion (once per role)
function Pose.prepare(role)
	local prepared = { channels = {}, faces = {}, clips = {} }
	for name, clip in pairs(role.clips) do
		local p = { duration = clip.duration, loop = clip.loop, additive = clip.additive, tracks = {}, face = {} }
		for channel, keys in pairs(clip.keys) do
			p.tracks[channel] = prepare(keys, clip.loop, clip.duration)
		end
		for pose, keys in pairs(clip.face or {}) do
			p.face[pose] = prepare(keys, clip.loop, clip.duration)
		end
		prepared.clips[name] = p
	end
	return prepared
end

function Pose.breath(duration, t)
	local count = math.max(1, math.floor(duration / Pose.BREATH + 0.5))
	return 1.2 * math.sin(2 * math.pi * t / (duration / count))
end

-- local rotations of the animated bones: {bone = quaternion} (Roblox frame).  greetT = time in the
-- greeting or nil.  channels: Pose.channelsOf(Motion, role) ({channel = {{bone, share}, ...}}).
-- breathBone: the bone that carries the breathing (default "spine01").
function Pose.evaluate(channels, prepared, clipName, t, greetT, breathBone)
	local clip = prepared.clips[clipName]
	if clip.loop then
		t = t % clip.duration
	end
	local greet = greetT and prepared.clips.greet
	local out = {}
	local a, g = { 0, 0, 0 }, { 0, 0, 0 }
	local mats = {}
	for channel, bones in pairs(channels) do
		local track = clip.tracks[channel]
		if track then
			sample(track, t, a)
		else
			a[1], a[2], a[3] = 0, 0, 0
		end
		local rx, ry, rz = a[1], a[2], a[3]
		if greet and greet.tracks[channel] then
			sample(greet.tracks[channel], greetT, g)
			rx, ry, rz = rx + g[1], ry + g[2], rz + g[3]
		end
		for _, entry in ipairs(bones) do
			local share = entry[2]
			mats[entry[1]] = euler(rx * share, ry * share, rz * share)
		end
	end
	local b = Pose.breath(clip.duration, t)
	local bb = breathBone or "spine01"
	mats[bb] = mul(mats[bb] or rot(1, 0, 0, 0), rot(1, 0, 0, -b))
	for bone, m in pairs(mats) do
		out[bone] = quat(toRoblox(m))
	end
	return out
end

-- expression weights {pose = 0..1} of a clip at time t
function Pose.faceWeights(prepared, clipName, t)
	local clip = prepared.clips[clipName]
	if clip.loop then
		t = t % clip.duration
	end
	local out, v = {}, { 0 }
	for pose, track in pairs(clip.face) do
		sample(track, t, v)
		out[pose] = math.max(0, math.min(1, v[1]))
	end
	return out
end

Pose.BREATH = 3.4

-- Per-role rig description.  A role of MarketMotion may bring its own channel table and bone names
-- (traders built on another skeleton, e.g. Lio on the Rigify rig); the others use the shared ones.
local DEFAULT_RIG = {
	breath = "spine01",
	neck = "neck01",
	head = "head",
	eyes = { "eye.L", "eye.R" },
	wrists = { L = "wrist.L", R = "wrist.R" },
}

function Pose.channelsOf(motion, role)
	local data = motion.roles[role]
	return (data and data.channels) or motion.channels
end

function Pose.rigOf(motion, role)
	local data = motion.roles[role]
	local rig = data and data.rig
	if not rig then return DEFAULT_RIG end
	return {
		breath = rig.breath or DEFAULT_RIG.breath,
		neck = rig.neck or DEFAULT_RIG.neck,
		head = rig.head or DEFAULT_RIG.head,
		eyes = rig.eyes or DEFAULT_RIG.eyes,
		wrists = rig.wrists or DEFAULT_RIG.wrists,
	}
end

return Pose
